# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">AKTİFLİK FARKININ STANDART PİL POTANSİYELİNE ETKİSİ</text>\n  <!-- Sol: Potansiyel Eksen Şeması -->\n  <rect x="25" y="42" width="310" height="202" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">STANDART İNDİRGENME POTANSİYELLERİ</text>\n  <line x1="75" y1="85" x2="75" y2="225" stroke="#1e3a8a" stroke-width="3"/>\n  <circle cx="75" cy="95" r="5" fill="#dc2626"/>\n  <text x="90" y="99" font-size="11.5" font-weight="bold" fill="#991b1b">Mg²⁺ + 2e⁻ → Mg   (E° = -2,37 V)</text>\n  <circle cx="75" cy="155" r="5" fill="#d97706"/>\n  <text x="90" y="159" font-size="11.5" font-weight="bold" fill="#92400e">Cr³⁺ + 3e⁻ → Cr    (E° = -0,74 V)</text>\n  <circle cx="75" cy="215" r="5" fill="#16a34a"/>\n  <text x="90" y="219" font-size="11.5" font-weight="bold" fill="#166534">Ag⁺ + e⁻ → Ag      (E° = +0,80 V)</text>\n  <!-- Sag: Karsilastirma -->\n  <rect x="355" y="42" width="320" height="202" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="515" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">AKTİFLİK FARKI VE VOLTAJ İLİŞKİSİ</text>\n  <rect x="372" y="80" width="286" height="58" rx="8" fill="#ffffff" stroke="#dc2626" stroke-width="1.8"/>\n  <text x="515" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">1. Mg - Ag Pili (Aktiflik Farkı Büyük)</text>\n  <text x="515" y="124" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#dc2626">E°_pil = +2,37 + 0,80 = 3,17 V</text>\n  <rect x="372" y="150" width="286" height="58" rx="8" fill="#ffffff" stroke="#d97706" stroke-width="1.8"/>\n  <text x="515" y="172" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">2. Cr - Ag Pili (Aktiflik Farkı Küçük)</text>\n  <text x="515" y="194" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b45309">E°_pil = +0,74 + 0,80 = 1,54 V</text>\n  <text x="515" y="230" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#78350f">Sonuç: Aktiflik farkı arttıkça pil potansiyeli artar.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">PİL POTANSİYELİNİ (E_pil) ETKİLEYEN VE ETKİLEMEYEN FAKTÖRLER</text>\n  <!-- Ust Denge Denklemi -->\n  <rect x="40" y="38" width="620" height="34" rx="6" fill="#e0e7ff" stroke="#4f46e5" stroke-width="1.5"/>\n  <text x="350" y="60" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#312e81">Denge: X(k) + Y²⁺(suda, Katot)  ⇌  X²⁺(suda, Anot) + Y(k) + ISI   (Ürünlere kayarsa E_pil ARTAR)</text>\n  <!-- Sol: Etkileyenler -->\n  <rect x="25" y="82" width="320" height="162" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="185" y="104" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">E_pil DEĞERİNİ DEĞİŞTİRENLER</text>\n  <text x="38" y="128" font-size="11.5" fill="#14532d">• Katot derişimini ([Y²⁺]) artırmak → E_pil ARTAR.</text>\n  <text x="38" y="150" font-size="11.5" fill="#14532d">• Anot derişimini ([X²⁺]) azaltmak → E_pil ARTAR.</text>\n  <text x="38" y="172" font-size="11.5" fill="#14532d">• Sıcaklığı azaltmak (soğutmak) → E_pil ARTAR.</text>\n  <text x="38" y="194" font-size="11.5" fill="#14532d">• Sıcaklığı artırmak (ısıtmak) → E_pil AZALIR.</text>\n  <text x="38" y="216" font-size="11.5" font-weight="bold" fill="#15803d">• Elektrotların ve çözeltilerin cinsini değiştirmek.</text>\n  <!-- Sag: Etkilemeyenler -->\n  <rect x="365" y="82" width="310" height="162" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="520" y="104" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">E_pil DEĞERİNİ ETKİLEMEYENLER</text>\n  <text x="380" y="132" font-size="12" fill="#7f1d1d">✗ Metal elektrotların kütlesi (miktarı)</text>\n  <text x="380" y="156" font-size="12" fill="#7f1d1d">✗ Elektrotların yüzey alanı ve şekli</text>\n  <text x="380" y="180" font-size="12" fill="#7f1d1d">✗ Sabit derişimde çözelti hacmi (V)</text>\n  <rect x="380" y="196" width="280" height="36" rx="6" fill="#fee2e2"/>\n  <text x="520" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">Bu nicelikler yalnız pilin ömrünü (süresini) etkiler.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">LİTYUM İYON PİLİNİN YAPISI VE ELEKTROT TEPKİMELERİ</text>\n  <!-- Sol: Yapı ve Tepkimeler -->\n  <rect x="25" y="42" width="345" height="202" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="197" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">YAPI VE YARI HÜCRE TEPKİMELERİ</text>\n  <rect x="38" y="78" width="318" height="42" rx="6" fill="#f3e8ff" stroke="#a855f7"/>\n  <text x="50" y="96" font-size="11.5" font-weight="bold" fill="#581c87">• Anot (Grafit):</text>\n  <text x="165" y="96" font-size="11.5" fill="#6b21a8">Li(k) → Li⁺ + e⁻  (Yükseltgenme)</text>\n  <text x="50" y="113" font-size="11.5" font-weight="bold" fill="#581c87">• Katot (CoO₂):</text>\n  <text x="165" y="113" font-size="11.5" fill="#6b21a8">Li⁺ + CoO₂ + e⁻ → LiCoO₂</text>\n  <rect x="38" y="128" width="318" height="36" rx="6" fill="#ffffff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="197" y="151" text-anchor="middle" font-size="12" font-weight="bold" fill="#581c87">Net Pil: Li(k) + CoO₂ → LiCoO₂   (E_pil ≈ 3,4 V)</text>\n  <text x="40" y="186" font-size="11.5" fill="#581c87">• Elektrolit: Susuz organik çözücü / lityum tuzu veya</text>\n  <text x="50" y="203" font-size="11.5" fill="#581c87">iyon geçişine izin veren katı polimer yapı.</text>\n  <text x="40" y="226" font-size="11.5" font-weight="bold" fill="#7e22ce">• Li standart indirgenme potansiyeli: -3,04 V (En aktif)</text>\n  <!-- Sag: Avantajlar ve Kullanim -->\n  <rect x="385" y="42" width="290" height="202" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="530" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">ÜSTÜNLÜKLERİ VE KULLANIMI</text>\n  <text x="400" y="92" font-size="11.5" fill="#7c2d12">✓ En küçük mol kütlesi → Çok hafif yapı.</text>\n  <text x="400" y="114" font-size="11.5" fill="#7c2d12">✓ Birim kütle başına yüksek enerji yoğunluğu.</text>\n  <text x="400" y="136" font-size="11.5" fill="#7c2d12">✓ Tekrar şarj edilebilir uzun çevrim ömrü.</text>\n  <text x="400" y="158" font-size="11.5" fill="#7c2d12">✓ 10 °C - 55 °C geniş çalışma sıcaklığı.</text>\n  <text x="400" y="180" font-size="11.5" fill="#7c2d12">✓ Düşük karbon salınımı ve çevreci özellik.</text>\n  <rect x="400" y="194" width="260" height="38" rx="6" fill="#ffedd5"/>\n  <text x="530" y="211" text-anchor="middle" font-size="11" font-weight="bold" fill="#9a3412">Kullanım Alanları: Cep telefonu, dizüstü</text>\n  <text x="530" y="226" text-anchor="middle" font-size="11" fill="#7c2d12">bilgisayar, elektrikli araç, kamera, kalp pili.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
